import"./chunk-2NFLSA4Y.js";var a={firstLaw:{theory:{concept:"[[The first law of thermodynamics: the change in the internal energy of a system equals the heat transferred to it minus the work done by the system: \u0394U = Q \u2212 W.]] It is the law of conservation of energy for thermal processes."},process:{isochoric:"Constant volume \u2014 locked piston",isobaric:"Constant pressure \u2014 free piston",adiabatic:"Adiabatic \u2014 thermally insulated"},param:{process:"Process",heat:"Total heat transferred to gas",ratio:"Final / initial volume",temperature:"Initial temperature",amount:"Amount of gas",volume:"Initial volume",timeStep:"Time step"},hint:{process:"Compare a locked piston, a piston under constant load, and an insulated cylinder.",heat:"Positive Q heats the gas; negative Q removes heat. This is total energy, not power.",ratio:"Below 1 compresses the insulated gas; above 1 expands it.",amount:"More gas needs more energy for the same temperature change."},preset:{cool:"Remove 100 J",zero:"No heat",heat:"Supply 300 J",compress:"Half the volume",expand:"Double the volume"},measure:{heat:"Heat supplied",work:"Work done by gas",deltaU:"Internal energy change",temperature:"Temperature",volume:"Volume",pressure:"Pressure",internalEnergy:"Internal energy",balance:"Energy balance residual"},graph:{energy:"Energy transfers and internal energy change",pv:"Pressure\u2013volume path"},view:{transfers:"Energy transfer arrows",particles:"Schematic particles",heatIn:"Heat supplied",heatOut:"Heat removed",workBy:"Gas does work",workOn:"Work done on gas",schematic:"Schematic, not to scale"},section:{energy:{title:"Internal energy",text:"Internal energy is the microscopic kinetic and interaction energy of particles. In a monatomic ideal gas it is the kinetic energy of random translational motion: U = 3nRT/2. A higher temperature means greater internal energy."},signs:{title:"Signs of heat and work",text:"[[Q is positive when heat enters the gas and negative when heat leaves.]] W is positive when the gas expands and does work on its surroundings; W is negative when the surroundings compress the gas. Compression can therefore raise internal energy even without heating."},isochoric:{title:"Constant volume",text:"A locked piston cannot move, so pressure-volume work is zero. All supplied heat changes internal energy: \u0394U = Q. Heating increases temperature and pressure; cooling reduces both."},isobaric:{title:"Constant pressure",text:"Under a constant load, heating moves the frictionless piston outward. Some heat increases internal energy and some becomes work: W = p\u0394V. For a monatomic ideal gas, 60% of the heat changes internal energy and 40% becomes work. These fractions are specific to this gas model."},adiabatic:{title:"No heat exchange",text:"[[In an insulated cylinder Q = 0, so \u0394U = \u2212W.]] Compression does work on the gas and raises its temperature; expansion makes the gas do work and cool down. For a reversible ideal-gas process, TV^(\u03B3\u22121) remains constant."}},formula:{first:"Conservation of energy; W is work done by the gas",work:"Work at constant pressure (1 kPa\xB7L = 1 J)",gas:"Ideal gas and internal energy change",capacity:"Molar heat capacities of a monatomic ideal gas",adiabatic:"Reversible adiabatic relation",integral:"Work equals the signed area under the p\u2013V path"},variable:{capacity:"Molar heat capacities",constant:"Gas constant (8.314)",gamma:"Heat-capacity ratio"},assumption:{ideal:"A monatomic ideal gas with constant heat capacities is used; real gases can behave differently.",piston:"The process is quasistatic; the gas is in equilibrium and the piston has no friction or inertia.",closed:"The gas amount is fixed. Only pressure-volume work is included; phase changes are excluded.",playback:"The six-second animation illustrates a sequence of equilibrium states; it does not predict the real heating time.",scale:"Cylinder, arrows and particles are schematic and not to scale. The dots do not calculate thermodynamic quantities."},challenge:{locked:{title:"Heat without moving the piston",description:"Increase internal energy by at least 290 J while the gas does no work.",hint:"Lock the piston and supply at least 300 J, then run the experiment."},expand:{title:"Make the gas do work",description:"Make the gas expand and perform at least 100 J of work.",hint:"At constant pressure, supply at least 250 J and run the experiment."},cool:{title:"Remove energy",description:"Remove heat and finish with lower temperature and internal energy.",hint:"Choose a process with heat exchange and set negative heat."},compress:{title:"Heat without supplying heat",description:"With Q = 0, increase temperature by at least 50% through compression.",hint:"Choose the adiabatic process and halve the volume."},split:{title:"Check the energy split",description:"Supply at least 100 J at constant pressure and verify that 40% becomes work while energy is conserved.",hint:"Run constant-pressure heating and compare Q, W and \u0394U."}}}},n={sim:a};export{n as default,a as sim};
